input.command:
export DSTASK_GIT_REPO=/tmp/labs/cliparse/ctx8
probe(){ /workspace/executable context none >/dev/null 2>&1; o=$(/workspace/executable context "$@" 2>&1); r=$?; o=$(printf '%s' "$o"|sed -e 's/\x1b\[[0-9;]*m//g'); g=$(/workspace/executable context 2>&1|sed -e 's/\x1b\[[0-9;]*m//g'); printf '%-26s rc=%s out=[%s] get=[%s]\n' "[$*]" "$r" "$(printf '%s' "$o"|tr '\n' '|')" "$g"; }
for t in "zzproject:x" "myproject:x" "aproject:x" "xproject:" "++project:x" "+-project:x" "-+project:x" "--project:x" "+project:" "zzdue:today" "zztemplate:1" "zzzdue.before:today" "+due.before:today" "-due.before:today"; do probe "$t"; done
